const j = $input.first().json;
let text = (j.output && j.output[0] && j.output[0].content && j.output[0].content[0] && j.output[0].content[0].text) || j.content || j.text || (j.message && j.message.content) || '';
if (typeof text !== 'string') text = JSON.stringify(text);
text = text.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) { const mm = text.match(/\{[\s\S]*\}/); if (mm) { try { parsed = JSON.parse(mm[0]); } catch (e2) {} } }
let graphics = Array.isArray(parsed.graphics) ? parsed.graphics : [];
const max = Number($('Resolve Content').first().json.maxInfographics) || 3;
graphics = graphics.filter(function (g) { return g && g.spec && g.anchor; }).slice(0, max);
if (graphics.length === 0) return [{ json: { _noGraphics: true } }];
return graphics.map(function (g, i) {
  let fn = String(g.fileName || ('infografika-' + (i + 1))).toLowerCase().replace(/\.(png|jpe?g|webp)$/, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 60);
  if (!fn) fn = 'infografika-' + (i + 1);
  return { json: { index: i, spec: String(g.spec), style: String(g.style || ''), anchor: String(g.anchor), altText: String(g.altText || g.spec).slice(0, 180), fileName: fn + '.jpg' } };
});

let results = [];
try { results = $('Build Result').all().map(function (i) { return i.json; }); } catch (e) { results = []; }
const survivors = $('Filter Graphics').all().map(function (i) { return i.json; }).filter(function (g) { return g && g.spec; });
let content = String($('Resolve Content').first().json.content || "");
const postId = $('Resolve Content').first().json.postId;
const replaceExisting = $('Resolve Content').first().json.replaceExisting !== false;
const dryRun = $('Resolve Content').first().json.dryRun === true;
const esc = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\"/g, "&quot;"); };
const stripTags = function (s) { return String(s == null ? "" : s).replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(); };
const OLD_RE = /<figure[^>]*class=\"[^\"]*wp-block-html[^\"]*\"[^>]*>[\s\S]*?<\/figure>/gi;
const isOld = function (block) { return block.indexOf("<svg") !== -1; };
const findOldBlocks = function (html) {
  const blocks = []; let m; OLD_RE.lastIndex = 0;
  while ((m = OLD_RE.exec(html)) !== null) { if (isOld(m[0])) blocks.push({ start: m.index, text: m[0] }); }
  return blocks;
};
const headingBefore = /<h[1-6][^>]*>[\s]*$/i;
const findAnchorPos = function (html, anchor) {
  if (!anchor) return -1;
  let tocEnd = 0;
  const tocM = html.match(/id=\"rank-math-toc\"[\s\S]*?<\/nav>/i);
  if (tocM) tocEnd = tocM.index + tocM[0].length;
  const tryText = function (needle) {
    if (!needle || needle.length < 5) return -1;
    let from = 0, idx, firstBody = -1;
    while ((idx = html.indexOf(needle, from)) !== -1) {
      from = idx + 1;
      if (idx < tocEnd) continue;
      if (firstBody === -1) firstBody = idx;
      const pre = html.slice(idx - 60 < 0 ? 0 : idx - 60, idx);
      if (headingBefore.test(pre)) return idx;
    }
    return firstBody;
  };
  let p = tryText(anchor);
  if (p !== -1) return p;
  const at = stripTags(anchor);
  p = tryText(at);
  if (p !== -1) return p;
  return tryText(at.slice(0, Math.min(50, at.length)));
};
let inserted = 0, replaced = 0;
const mediaIds = [];
const okResults = results.filter(function (r) { return r && r.status === "inserted" && r.mediaId; });
okResults.sort(function (a, b) { return (a.index || 0) - (b.index || 0); });
for (const r of okResults) {
  const figure = '<figure class=\"wp-block-image size-large\"><img src=\"' + r.sourceUrl + '\" alt=\"' + esc(r.alt) + '\" class=\"wp-image-' + r.mediaId + '\" /></figure>';
  if (content.indexOf("wp-image-" + r.mediaId) !== -1) { inserted++; mediaIds.push(r.mediaId); continue; }
  const rawAnchor = String(r.anchor || "");
  const pos = findAnchorPos(content, rawAnchor);
  let done = false;
  if (replaceExisting) {
    const oldBlocks = findOldBlocks(content);
    if (oldBlocks.length) {
      let best = null, bestDist = Infinity;
      for (const b of oldBlocks) { const d = pos === -1 ? b.start : Math.abs(b.start - pos); if (d < bestDist) { bestDist = d; best = b; } }
      if (best) { content = content.slice(0, best.start) + figure + content.slice(best.start + best.text.length); inserted++; replaced++; mediaIds.push(r.mediaId); done = true; }
    }
  }
  if (!done) {
    if (pos === -1) { continue; }
    const rest = content.slice(pos);
    const mm = rest.match(/<\/(h[1-6]|p|ul|ol|table|figure|blockquote|div|section)>/i);
    const insertPos = mm ? pos + mm.index + mm[0].length : (pos + rawAnchor.length);
    content = content.slice(0, insertPos) + figure + content.slice(insertPos);
    inserted++; mediaIds.push(r.mediaId);
  }
}
const skipped = Math.max(0, survivors.length - inserted);
return [{ json: { updatedContent: content, postId: postId, inserted: inserted, skipped: skipped, replaced: replaced, mediaIds: mediaIds, dryRun: dryRun } }];

const items = $input.all();
let content = String($('Resolve Content').first().json.content || "");
const stripTags = function (s) { return String(s == null ? "" : s).replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(); };
const headingBefore = /<h[1-6][^>]*>[\s]*$/i;
const findAnchorPos = function (html, anchor) {
  if (!anchor) return -1;
  let tocEnd = 0;
  const tocM = html.match(/id="rank-math-toc"[\s\S]*?<\/nav>/i);
  if (tocM) tocEnd = tocM.index + tocM[0].length;
  const tryText = function (needle) {
    if (!needle || needle.length < 5) return -1;
    let from = 0, idx, firstBody = -1;
    while ((idx = html.indexOf(needle, from)) !== -1) {
      from = idx + 1;
      if (idx < tocEnd) continue;
      if (firstBody === -1) firstBody = idx;
      const pre = html.slice(idx - 60 < 0 ? 0 : idx - 60, idx);
      if (headingBefore.test(pre)) return idx;
    }
    return firstBody;
  };
  let p = tryText(anchor);
  if (p !== -1) return p;
  const at = stripTags(anchor);
  p = tryText(at);
  if (p !== -1) return p;
  return tryText(at.slice(0, Math.min(50, at.length)));
};
const out = [];
for (const it of items) {
  const g = it.json || {};
  if (!g.spec || g._noGraphics) continue;
  if (findAnchorPos(content, String(g.anchor || "")) === -1) continue;
  out.push({ json: g });
}
if (out.length === 0) return [{ json: { _noGraphics: true } }];
return out;

const gen = $input.all();
const plan = $('Filter Graphics').all();
return gen.map(function (it, i) {
  const p = (plan[i] && plan[i].json) || {};
  return { json: Object.assign({}, it.json, { index: p.index, anchor: p.anchor, altText: p.altText, fileName: p.fileName, style: p.style }), binary: it.binary };
